var source = new ReportSource(
    Id: "Serilog",
    Downloads: 500_000_000,
    Dependencies: new() { new() { Name = "Serilog.Sinks.Console", Version = "5.0.0" } },
    Diagnostics: new() { new() { Level = "warning", Text = "transitive version conflict" } });

// 1. Quiet: title + scalars only. Base verbosity collects no detail; render no sections.
Render("QUIET", source, Verbosity.Quiet);

// 2. Diagnostics-only: naming the deepest section PROMOTES the effective verbosity so Diagnostics
//    (and everything shallower) is collected, yet IncludeSections renders ONLY Diagnostics —
//    Dependencies is collected but deliberately not rendered.
Render("DIAGNOSTICS ONLY", source, Verbosity.Quiet, Section.Diagnostics);

// 3. Detailed: collect and render both detail sections.
Render("DETAILED", source, Verbosity.Detailed);

static void Render(string label, ReportSource source, Verbosity baseVerbosity, params string[] targeted)
{
    // Naming a section promotes the effective verbosity to that section's depth so its data is
    // collected. Effective verbosity is the max of the base level and every targeted section's level.
    var effective = baseVerbosity;
    foreach (var name in targeted)
    {
        if (Section.MinVerbosity[name] > effective)
        {
            effective = Section.MinVerbosity[name];
        }
    }

    var report = Collect(source, effective);

    // Choose which collected sections actually render. When sections are targeted by name, render
    // exactly those; otherwise render every section the effective verbosity collected.
    var include = targeted.Length > 0
        ? new HashSet<string>(targeted)
        : new HashSet<string>(
            Section.MinVerbosity
                .Where(kv => kv.Value <= effective)
                .Select(kv => kv.Key));

    var options = new MarkoutWriterOptions { IncludeSections = include };

    Console.WriteLine($"===== {label} =====");
    MarkoutSerializer.Serialize(report, Console.Out, new MarkdownFormatter(), ReportContext.Default, options);
    Console.WriteLine();
}

// Populate the model's detail lists only when the effective verbosity is high enough to collect
// them. This is the "collection" gate: shallower detail is always collected before deeper detail.
static PackageReport Collect(ReportSource source, Verbosity effective) => new()
{
    Id = source.Id,
    Downloads = source.Downloads,
    Dependencies = effective >= Verbosity.Normal ? source.Dependencies : new(),
    Diagnostics = effective >= Verbosity.Detailed ? source.Diagnostics : new(),
};

// Increasing depth of detail. Diagnostics is the deepest/most expensive detail.
enum Verbosity
{
    Quiet = 0,    // title + scalars only
    Normal = 1,   // + Dependencies
    Detailed = 2, // + Diagnostics (deepest)
}

// Section names (matched by IncludeSections) paired with the verbosity required to collect them.
static class Section
{
    public const string Dependencies = "Dependencies";
    public const string Diagnostics = "Diagnostics";

    public static readonly Dictionary<string, Verbosity> MinVerbosity = new()
    {
        [Dependencies] = Verbosity.Normal,
        [Diagnostics] = Verbosity.Detailed,
    };
}

