{"path":"/var/folders/09/c3s_t1kd4m91p7yltrx08snw0000gn/T/sv-882c1b083efa439b812edf4d3c313ef5/Program.new.cs","file_text":"using Markout;

// Raw detail data lives in one place. Collecting a section is "expensive", so the builder
// only attaches a section when the effective verbosity is high enough to warrant it.
var deps = new List<Dep> { new() { Name = "Serilog.Sinks.Console", Version = "5.0.0" } };
var diags = new List<Diagnostic> { new() { Level = "warning", Text = "transitive version conflict" } };

// --- One model definition, three views ---------------------------------------------------

// 1. Quiet: title + scalars only. Nothing is collected, nothing to render.
Render(Build(Verbosity.Quiet, targets: null), targets: null);

Console.WriteLine();

// 2. Target ONLY "Diagnostics". Diagnostics is the deepest detail, so naming it PROMOTES the
//    effective verbosity to Diagnostic — which also collects Dependencies. IncludeSections then
//    restricts RENDERING to Diagnostics alone: collected != rendered.
var diagnosticsOnly = new HashSet<string> { "Diagnostics" };
Render(Build(Verbosity.Quiet, diagnosticsOnly), diagnosticsOnly);

Console.WriteLine();

// 3. Detailed: deepest verbosity collects everything; no filter renders everything.
Render(Build(Verbosity.Diagnostic, targets: null), targets: null);

PackageReport Build(Verbosity baseLevel, ISet<string>? targets)
{
    // Promotion: targeting a section raises the effective verbosity to that section's requirement.
    var effective = baseLevel;
    if (targets is not null)
        foreach (var section in targets)
            effective = (Verbosity)Math.Max((int)effective, (int)RequiredLevel(section));

    return new PackageReport
    {
        Id = "Serilog",
        Downloads = 500_000_000,
        // Collect a section only when the effective verbosity meets its cost threshold.
        Dependencies = effective >= Verbosity.Detailed ? deps : null,
        Diagnostics = effective >= Verbosity.Diagnostic ? diags : null,
    };
}

static Verbosity RequiredLevel(string section) => section switch
{
    "Diagnostics" => Verbosity.Diagnostic,
    "Dependencies" => Verbosity.Detailed,
    _ => Verbosity.Quiet,
};

static void Render(PackageReport report, ISet<string>? targets)
{
    var options = new MarkoutWriterOptions();
    if (targets is not null)
        options.IncludeSections = new HashSet<string>(targets);
    MarkoutSerializer.Serialize(report, Console.Out, new MarkdownFormatter(), PackageReportContext.Default, options);
}

enum Verbosity { Quiet = 0, Detailed = 1, Diagnostic = 2 }

[MarkoutSerializable(TitleProperty = nameof(Id))]
public sealed class PackageReport
{
    public string Id { get; init; } = "";

    [MarkoutDisplayFormat("{0:N0} downloads")]
    public long Downloads { get; init; }

    [MarkoutSection(Name = "Dependencies")]
    public List<Dep>? Dependencies { get; init; }

    [MarkoutSection(Name = "Diagnostics")]
    public List<Diagnostic>? Diagnostics { get; init; }
}

public sealed class Dep { public string Name { get; init; } = ""; public string Version { get; init; } = ""; }

public sealed class Diagnostic { public string Level { get; init; } = ""; public string Text { get; init; } = ""; }

[MarkoutContext(typeof(PackageReport))]
[MarkoutContext(typeof(Dep))]
[MarkoutContext(typeof(Diagnostic))]
